CREATE TABLE material_consumption_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,work_scope_snapshot_id uuid NOT NULL,norm_snapshot_id uuid NOT NULL,knowledge_version_id uuid NOT NULL,technology_version_id uuid NOT NULL,work_item_id uuid NOT NULL,code varchar(80) NOT NULL,title varchar(300) NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,work_scope_snapshot_id)REFERENCES approved_work_scope_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,norm_snapshot_id)REFERENCES approved_engineering_norm_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,knowledge_version_id)REFERENCES construction_knowledge_versions(tenant_id,id),FOREIGN KEY(tenant_id,technology_version_id)REFERENCES execution_technology_versions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE material_consumption_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','ready_for_approval','approved','superseded','cancelled')),is_current boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,approved_at timestamptz,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,run_id,revision_number),FOREIGN KEY(tenant_id,run_id)REFERENCES material_consumption_runs(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE UNIQUE INDEX uq_material_consumption_current ON material_consumption_revisions(tenant_id,run_id)WHERE is_current;
CREATE TABLE material_consumption_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,revision_id uuid NOT NULL,requirement_code varchar(120) NOT NULL,engineering_requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(engineering_requirements)='object'),environmental_requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(environmental_requirements)='object'),demand_formula jsonb NOT NULL CHECK(jsonb_typeof(demand_formula)='object'),norm_revision_number integer NOT NULL CHECK(norm_revision_number>0),technology_version_id uuid NOT NULL,net_quantity numeric(20,8) NOT NULL CHECK(net_quantity>=0),unit_code varchar(40) NOT NULL,material_id uuid,selection_reason varchar(2000),substitutes_material_id uuid,selection_state text NOT NULL DEFAULT'unselected'CHECK(selection_state IN('unselected','selected','substitution_selected')),package_type varchar(80),package_size numeric(20,8)CHECK(package_size>0),package_unit_code varchar(40),rounding_rule_code varchar(80),rounding_rule_version varchar(80),waste_policy jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(waste_policy)='object'),waste_quantity numeric(20,8) NOT NULL DEFAULT 0 CHECK(waste_quantity>=0),reserve_quantity numeric(20,8) NOT NULL DEFAULT 0 CHECK(reserve_quantity>=0),total_quantity numeric(20,8) NOT NULL DEFAULT 0 CHECK(total_quantity>=0),package_count bigint NOT NULL DEFAULT 0 CHECK(package_count>=0),package_remainder numeric(20,8) NOT NULL DEFAULT 0 CHECK(package_remainder>=0),available_quantity numeric(20,8) NOT NULL DEFAULT 0 CHECK(available_quantity>=0),remaining_quantity numeric(20,8) NOT NULL DEFAULT 0 CHECK(remaining_quantity>=0),availability_source_reference varchar(300),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id,requirement_code),FOREIGN KEY(tenant_id,run_id)REFERENCES material_consumption_runs(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES material_consumption_revisions(tenant_id,id),FOREIGN KEY(tenant_id,technology_version_id)REFERENCES execution_technology_versions(tenant_id,id),FOREIGN KEY(tenant_id,material_id)REFERENCES materials(tenant_id,id),FOREIGN KEY(tenant_id,substitutes_material_id)REFERENCES materials(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((available_quantity=0)OR availability_source_reference IS NOT NULL),CHECK((selection_state='unselected'AND material_id IS NULL)OR(selection_state<>'unselected'AND material_id IS NOT NULL)));
CREATE TABLE approved_material_consumption_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,revision_id uuid NOT NULL,revision_number integer NOT NULL,project_id uuid NOT NULL,content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'AND pg_column_size(content)<=4194304),content_fingerprint char(64) NOT NULL,schema_version varchar(40) NOT NULL DEFAULT'material-consumption-v1',approved_at timestamptz NOT NULL DEFAULT now(),approved_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id),FOREIGN KEY(tenant_id,run_id)REFERENCES material_consumption_runs(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES material_consumption_revisions(tenant_id,id),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id));
CREATE FUNCTION protect_approved_material_consumption_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'APPROVED_MATERIAL_CONSUMPTION_SNAPSHOT_IMMUTABLE';END$$;CREATE TRIGGER immutable_approved_material_consumption_snapshot BEFORE UPDATE OR DELETE ON approved_material_consumption_snapshots FOR EACH ROW EXECUTE FUNCTION protect_approved_material_consumption_snapshot();
CREATE FUNCTION protect_approved_material_consumption_content()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE rid uuid;state text;BEGIN rid=CASE WHEN TG_OP='DELETE'THEN OLD.revision_id ELSE NEW.revision_id END;SELECT status INTO state FROM material_consumption_revisions WHERE id=rid;IF state IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_MATERIAL_CONSUMPTION_IMMUTABLE';END IF;IF TG_OP='DELETE'THEN RETURN OLD;END IF;RETURN NEW;END$$;CREATE TRIGGER immutable_material_consumption_lines BEFORE INSERT OR UPDATE OR DELETE ON material_consumption_lines FOR EACH ROW EXECUTE FUNCTION protect_approved_material_consumption_content();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['material_consumption_runs','material_consumption_revisions','material_consumption_lines','approved_material_consumption_snapshots']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_%I ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
CREATE INDEX idx_material_consumption_project ON material_consumption_runs(tenant_id,project_id,updated_at DESC);CREATE INDEX idx_material_consumption_lines ON material_consumption_lines(tenant_id,revision_id,requirement_code);CREATE INDEX idx_material_consumption_material ON material_consumption_lines(tenant_id,material_id);
INSERT INTO permissions(code,description)VALUES('material_consumption.create','Create material consumption runs'),('material_consumption.read','Read material consumption runs'),('material_consumption.edit','Select compatible materials and govern quantities'),('material_consumption.review','Review material consumption readiness'),('material_consumption.approve','Approve authoritative material consumption'),('material_consumption.snapshots.read','Read approved material consumption snapshots')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE(r.code IN('tenant_admin','project_manager')AND p.code LIKE'material_consumption.%')OR(r.code='employee'AND p.code IN('material_consumption.create','material_consumption.read','material_consumption.edit','material_consumption.review'))OR(r.code='read_only'AND p.code IN('material_consumption.read','material_consumption.snapshots.read'))ON CONFLICT DO NOTHING;
